// Net-terms aging: keep only overdue OPEN / INVOICE_SENT wholesale drafts and write each reminder.
const nodes = $json?.data?.draftOrders?.nodes ?? [];
const out = [];
for (const d of nodes) {
  if (d.status === 'COMPLETED') continue;
  const tags = d.tags || [];
  if (!tags.includes('wholesale') && !tags.some(t => t.startsWith('po-'))) continue; // wholesale drafts only
  const daysOpen = Math.floor((Date.now() - Date.parse(d.createdAt)) / 86400000);
  const m = /payment terms:\s*net-(\d+)/i.exec(d.note || '');
  const netDays = m ? parseInt(m[1], 10) : 30; // assume net-30 when note missing
  if (daysOpen <= netDays) continue;
  const daysOver = daysOpen - netDays;
  const po = tags.find(t => t.startsWith('po-'))?.replace(/^po-/, '') || d.name;
  const name = d.customer?.displayName || 'there';
  out.push({ json: {
    name: d.name, po, daysOver, total: d.totalPrice, invoiceUrl: d.invoiceUrl,
    to: d.email || '',
    subject: `Friendly reminder — invoice ${d.name}${po ? ` (PO ${po})` : ''}`,
    body: `Hi ${name},\n\nHope you're doing well! Quick reminder that invoice ${d.name}${po ? ` for PO ${po}` : ''} ($${d.total}) is ${daysOver} day${daysOver === 1 ? '' : 's'} past its net-${netDays} terms.\n\nYou can pay in one click here: ${d.invoiceUrl || '(invoice link in Shopify Admin → Orders → Drafts)'}\n\nIf it's already in motion, thank you — and ignore this note.\n\nBest,\nThe team`,
  } });
}
if (out.length === 0) out.push({ json: { skipped: 'Nothing overdue this week 🎉' } });
return out;
